<script lang="ts">
  import type {AppData} from '#lib/client/types.ts';
  import {guides} from '#lib/client/help-content.ts';
  import {fieldHelp} from '#lib/client/field-help.ts';
  import {permitted} from '#lib/client/api.ts';
  import Icon from './Icon.svelte';
  let {data,available,onchat,onaction}:{data:AppData;available:boolean;onchat:(prompt:string)=>void;onaction:(action:string)=>void}=$props();
  const slug=$derived(data.path?.split('/')[0]??'');
  const studio=$derived(data.view==='studio');
  const kind=$derived(data.detail?.kind==='room_plan'?'room':'memorial');
  const mapping:Record<string,string>={customers:'customer',inquiries:'customer',orders:'orders',quotes:'sales','change-orders':'sales',invoices:'finance',payments:'finance',suppliers:'purchasing','purchase-orders':'purchasing',stock:'inventory',inventory:'inventory',team:'team',time:'time',documents:'documents',reports:'reports',settings:'ai',account:'orientation'};
  const guide=$derived(guides.find(g=>g.id===(studio?kind:mapping[slug]??'orientation')&&(!g.permission||permitted(data,g.permission)))??guides.find(g=>g.id==='orientation')!);
  const title=$derived(data.module?.label??(studio?'Planungsstudio':slug==='dispatch'?'Einsatzplanung':slug==='settings'?'Einstellungen':slug==='account'?'Meine Einstellungen':'Heute'));
  const fields=$derived((data.module?.fields??[]).filter(field=>field.required&&fieldHelp(field)).slice(0,5));
  const suggestions=$derived(studio?(kind==='room'?[
    {label:'Aus Skizze oder Maßen starten',prompt:'Ich möchte aus einer Skizze oder meinen Maßen einen bearbeitbaren Grundriss erstellen. Frage mich nach den lichten Innenmaßen, Raumhöhe, Wandstärke und den vorhandenen Unterlagen. Bereite erst nach Klärung einen Entwurf zur Vorschau vor.'},
    {label:'Raumaufteilung besprechen',prompt:'Hilf mir, diesen Raum weiterzuplanen. Prüfe die vorhandenen Maße, Öffnungen und Bewegungsflächen und frage gezielt nach fehlenden Angaben.'},
    {label:'Ausgewähltes Objekt ändern',prompt:'Ich möchte die ausgewählte Komponente ändern. Frage mich nach der gewünschten Position oder Größe und bereite anschließend einen prüfbaren Änderungsvorschlag vor.'},
    {label:'Materialkonzept entwickeln',prompt:'Entwickle mit mir ein stimmiges Naturstein- und Materialkonzept für diesen Raum. Berücksichtige vorhandene Produkte und frage nach meinen Gestaltungswünschen.'}
  ]:[
    {label:'Mit einem Grabmalentwurf beginnen',prompt:'Ich möchte einen bearbeitbaren Grabmalentwurf aus meinen Maßen oder einer Skizze beginnen. Frage gezielt nach Breite, Höhe, Stärke und meinen Gestaltungswünschen. Bereite danach eine Vorschau vor.'},
    {label:'Inschrift gestalten',prompt:'Hilf mir, die vorhandenen Inschriftgruppen ruhig und stimmig anzuordnen. Bewahre Namen, Daten und Wortlaut exakt. Frage mich nach der gewünschten Größe und Ausrichtung.'},
    {label:'Grabmal weiterentwickeln',prompt:'Besprich mit mir die Gestaltung dieses Grabmals. Berücksichtige Stein, Einfassung, Material und Bestand. Frage zuerst nach den konkreten Änderungswünschen.'},
    {label:'Planstand prüfen',prompt:'Prüfe den gespeicherten Grabmalentwurf und nenne die drei wichtigsten noch offenen Angaben für die nächste Planung.'}
  ]):[{label:'Nächsten Schritt besprechen',prompt:'Was ist auf dieser Seite der sinnvolle nächste Schritt? Beziehe dich auf den aktuellen Vorgang und frage nach fehlenden Angaben.'},{label:'Vorgang zusammenfassen',prompt:'Fasse den aktuellen Vorgang kurz zusammen. Unterscheide bestätigte Angaben und offene Punkte.'}]);
</script>
<div class="companion-home">
  <section class="companion-intro"><h3>Wie kann ich helfen?</h3><p>Sie sind gerade in <strong>{title}</strong>. Hier finden Sie passende Hilfen und können Ihr Vorhaben im Chat besprechen.</p></section>
  <details open class="companion-guide"><summary><Icon name="help" size={18}/>Diese Seite verstehen</summary><p>{slug==='dispatch'?'Wechseln Sie zwischen Tag, Woche und Monat. Ein Tag öffnet seine Einsätze; ein Einsatz führt zur bearbeitbaren Akte.':guide.intro}</p><ol>{#each slug==='dispatch'?['Wählen Sie Tag, Woche oder Monat und den gewünschten Zeitraum.','Filtern Sie bei Bedarf nach einem Mitarbeiter. Ein Klick auf einen Tag zeigt alle Einsätze darunter.','Öffnen Sie einen Einsatz zum Bearbeiten. Neue Einsätze legen Sie über die Aktion oben auf der Seite an.']:guide.steps as step}<li>{step}</li>{/each}</ol><span class="local-help"><Icon name="check" size={13}/>Sofort verfügbar · ohne KI-Verbrauch</span></details>
  {#if studio&&data.detail?.id}<section class="companion-tools"><h4>Mit der Planung weiterarbeiten</h4><button onclick={()=>onaction('image')}><Icon name="image" size={19}/><span>Realistisches Bild erstellen<small>Material, Licht und Perspektive gestalten</small></span><Icon name="arrow" size={16}/></button><button onclick={()=>onaction('photo')}><Icon name="camera" size={19}/><span>{kind==='memorial'?'Bestehendes Grabfoto bearbeiten':'Raumfoto als Grundlage verwenden'}<small>Foto auswählen und Änderungen beschreiben</small></span><Icon name="arrow" size={16}/></button><button onclick={()=>onaction('exports')}><Icon name="download" size={19}/><span>Pläne und Unterlagen ausgeben<small>Gespeicherten Stand prüfen und exportieren</small></span><Icon name="arrow" size={16}/></button></section>{/if}
  {#if fields.length}<details class="companion-guide"><summary><Icon name="file" size={18}/>Was trage ich hier ein?</summary><dl>{#each fields as field}<div><dt>{field.label}</dt><dd>{fieldHelp(field)}</dd></div>{/each}</dl></details>{/if}
  {#if available}<section class="companion-suggestions"><h4>Gemeinsam besprechen</h4>{#each suggestions as suggestion}<button onclick={()=>onchat(suggestion.prompt)}>{suggestion.label}<Icon name="arrow" size={15}/></button>{/each}<p>Der Vorschlag erscheint zuerst im Eingabefeld. Erst „Senden“ startet eine KI-Anfrage.</p></section>{/if}
  <a class="companion-help-link" href={'/help?from='+encodeURIComponent(slug)} onclick={()=>onaction('close')}>Hilfebereich und Einführung<Icon name="arrow" size={16}/></a>
</div>
