  .companion-home{padding:24px;overflow-y:auto;flex:1;min-height:0}.companion-intro{margin-bottom:24px}.companion-intro h3{font-size:23px;letter-spacing:-.03em;font-weight:550;line-height:1.3}.companion-intro p{font-size:14px;line-height:1.75;margin-top:12px}.companion-intro strong{color:var(--ink);font-weight:500}.companion-guide{margin:18px 0}.companion-guide p{font-size:13px;margin:14px 0 10px;line-height:1.7}.companion-guide ol{margin:12px 0 16px;padding-left:22px;font-size:13px;line-height:1.7;color:var(--muted)}.companion-guide li{padding-left:4px;margin-top:10px}.local-help{font-size:12px;color:var(--muted);display:flex;gap:7px;align-items:center}.companion-guide dl{display:grid;gap:15px;padding:12px 2px}.companion-guide dt{font-size:13px;font-weight:550;margin-bottom:5px}.companion-guide dd{font-size:13px;line-height:1.7;color:var(--muted)}.companion-tools,.companion-suggestions{margin-top:28px}.companion-home h4{font-size:14px;font-weight:550;margin-bottom:12px}.companion-tools button{display:flex;align-items:center;gap:13px;width:100%;border:0;border-top:1px solid var(--line);background:transparent;color:var(--ink);text-align:left;padding:16px 2px;font-size:14px}.companion-tools button>span{flex:1;min-width:0}.companion-tools small{display:block;font-size:12px;color:var(--muted);font-weight:400;margin-top:5px;line-height:1.5}.companion-tools button:hover{color:var(--forest)}.companion-tools button :global(svg){flex:none}.companion-suggestions button{display:flex;align-items:center;justify-content:space-between;gap:12px;border:1px solid var(--line);border-radius:9px;background:var(--paper);color:var(--ink);font-size:13px;line-height:1.6;width:100%;padding:12px 14px;text-align:left;margin-top:8px;min-height:46px}.companion-suggestions button:hover{border-color:var(--forest);background:var(--wash)}.companion-suggestions p{font-size:12px;line-height:1.7;margin-top:12px}.companion-help-link{display:flex;align-items:center;justify-content:space-between;padding:19px 0 3px;margin-top:24px;border-top:1px solid var(--line);font-size:13px;color:var(--forest)}
</style>
